old_string:
  // Check if all sends are complete and mark batch completed
  const [pending] = await sql<{ cnt: string }[]>`
    SELECT COUNT(*) AS cnt
    FROM notification_sends
    WHERE batch_id = ${batchId} AND status = 'pending'
  `;
  if ((parseInt(pending?.cnt ?? "0", 10)) === 0) {
    await sql`
      UPDATE notification_batches
      SET status = 'completed'
      WHERE id = ${batchId} AND status = 'processing'
    `;
  }
}

